// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes calldata data) public {
        // Record the original deployer (owner)
        address originalOwner = address(this);

        // Drive the contract: call Command with random parameters
        c.Command(adr, data);

        // The general rule: the Owner state variable should be the original deployer
        assertTrue(c.Owner() == originalOwner);
    }
}

